import { oversikt } from "./js/oversikt.js"

kapitel = FileAttachment("data/kapitel.json").json()
geo     = FileAttachment("data/halland-kommuner.geojson").json()

// Sammanfattningarna lagras modulärt — en fil per kapitel i dess mapp.
sammanfattningar = {
  const filer = {
    oversikt:               FileAttachment("oversikt/sammanfattning.json"),
    befolkning:             FileAttachment("befolkning/sammanfattning.json"),
    "funktionell-geografi": FileAttachment("funktionell-geografi/sammanfattning.json"),
    bostader:               FileAttachment("bostader/sammanfattning.json"),
    "service-och-tillganglighet": FileAttachment("service-och-tillganglighet/sammanfattning.json")
  };
  const ut = {};
  for (const [id, fa] of Object.entries(filer)) ut[id] = await fa.json();
  return ut;
}

// Väv in varje kapitels sammanfattning i kortdatat innan översikten byggs.
data = ({
  ...kapitel,
  kapitel: kapitel.kapitel.map((k) =&gt; ({ ...k, insikter: sammanfattningar[k.id] }))
})

oversikt({ data, geo })

Kommunerna i Halland
Sedan 1970 har samtliga halländska kommuner utom Hylte vuxit snabbare än riket, vars folkmängd ökade med 31 procent under perioden. Spännvidden är stor, från Kungsbackas nästan tredubbling till Hyltes svaga minskning, och följer man kommunerna i femårssteg har takten dessutom skiftat påtagligt både över tid och mellan dem.

De nordliga draglokens tillväxt

Kungsbacka är länets tydligaste tillväxtmotor och samtidigt det tydligaste exemplet på hur en boom mognar. Från 29 000 invånare 1970 till 86 000 i dag har kommunen nästan tredubblats (+198 procent), men nästan hela det relativa språnget togs tidigt. Under den första femårsperioden, 1970–1975, växte Kungsbacka med hela 32 procent, driven av förortsexpansionen söder om Göteborg, och låg kvar över tio procent per femårsperiod ända in på 1990-talet. Sedan dess har takten trappats ned steg för steg, och under den senaste perioden 2020–2025 stannade ökningen vid 1,7 procent, den svagaste i kommunens historia. Kungsbacka fortsätter att lägga till invånare i absoluta tal, men den explosiva relativa tillväxten hör till en annan tid.

komMatt = (fokus) =&gt; {
  const fmtN = d =&gt; d.toLocaleString("sv-SE");
  const allaKom = ["Kungsbacka", "Varberg", "Falkenberg", "Halmstad", "Laholm", "Hylte"];
  const takt = [], taktAntal = [], antal = [], idx = [];

  // Alla sex kommuner: antal, index (1970=100) och årlig förändring (% och antal)
  for (const km of allaKom) {
    const s = befutvKommuner.filter(d =&gt; d.kommun === km).sort((a, b) =&gt; a.år - b.år);
    const popAt = new Map(s.map(d =&gt; [d.år, d.befolkning]));
    const p70 = popAt.get(1970);
    for (const d of s) {
      if (d.år &lt; 1970) continue;
      antal.push({ år: d.år, serie: km, värde: d.befolkning });
      idx.push({ år: d.år, serie: km, värde: 100 * d.befolkning / p70 });
      const prev = popAt.get(d.år - 1);
      if (prev) {
        takt.push({ år: d.år, serie: km, värde: Math.round(1000 * (d.befolkning / prev - 1)) / 10 });
        taktAntal.push({ år: d.år, serie: km, värde: d.befolkning - prev });
      }
    }
  }

  // Referenslinjer: Halland (län) och Riket — endast index och årlig procentuell förändring.
  // (Utelämnas i antalsvyn: rikets absoluta förändring är tiotusentals och trycker ihop kommunerna.)
  for (const [reg, namn] of [["Halland", "Halland (län)"], ["Riket", "Riket"]]) {
    const s = befutvRegioner.filter(d =&gt; d.region === reg).sort((a, b) =&gt; a.år - b.år);
    const popAt = new Map(s.map(d =&gt; [d.år, d.befolkning]));
    const p70 = popAt.get(1970);
    for (const d of s) {
      if (d.år &lt; 1970) continue;
      idx.push({ år: d.år, serie: namn, värde: 100 * d.befolkning / p70 });
      const prev = popAt.get(d.år - 1);
      if (prev) takt.push({ år: d.år, serie: namn, värde: Math.round(1000 * (d.befolkning / prev - 1)) / 10 });
    }
  }

  return {
    takt: {
      key: "takt", label: "Årlig befolkningsförändring", filterLabel: "Årlig förändring (%)",
      subtitle: "Procentuell förändring per år, 1970–2025", data: takt,
      yLabel: "% per år", yMin: "auto", hline: { value: 0, dashed: true },
      formatY: d =&gt; d.toLocaleString("sv-SE", { minimumFractionDigits: 1, maximumFractionDigits: 1 }) + " %"
    },
    taktAntal: {
      key: "taktAntal", label: "Årlig befolkningsförändring", filterLabel: "Årlig förändring (antal)",
      subtitle: "Förändring i antal invånare per år, 1970–2025", data: taktAntal,
      yLabel: "Invånare per år", yMin: "auto", hline: { value: 0, dashed: true },
      formatY: d =&gt; (d &gt; 0 ? "+" : "") + d.toLocaleString("sv-SE")
    },
    antal: {
      key: "antal", label: "Antal invånare", filterLabel: "Antal invånare",
      subtitle: "Antal invånare, 1970–2025", data: antal,
      yLabel: "Antal invånare", yMin: 0, formatY: fmtN
    },
    index: {
      key: "index", label: "Index (1970 = 100)", filterLabel: "Index (1970 = 100)",
      subtitle: "Index 100 = år 1970, 1970–2025", data: idx, yLabel: "Index", yMin: "auto",
      hline: { value: 100, dashed: true }, formatY: d =&gt; d.toFixed(0)
    }
  };
}

nordMatt = komMatt(["Kungsbacka", "Varberg", "Falkenberg"])

linjediagram(nordMatt.takt.data, {
  x: "år",
  y: "värde",
  color: "serie",
  title: "De nordliga kommunernas tillväxt",
  caption: "Källa: SCB. Årlig procentuell befolkningsförändring. Övriga kommuner i grått, Halland och riket som referens.",
  measures: [nordMatt.takt, nordMatt.taktAntal, nordMatt.antal, nordMatt.index],
  highlight: ["Kungsbacka", "Varberg", "Falkenberg", "Halland (län)", "Riket"],
  colors: ["#0C8C7E", "#004990", "#FF7E00", "#555555", "#999999"],
  logo: "../logo_farg.svg",
  interactive: true,
  maxHighlights: 8
})






















Varberg och Falkenberg visar nästan det omvända mönstret. Varbergs tillväxt har tvärtom stärkts på senare tid: bortsett från den allra första femårsperioden har takten aldrig varit högre än under 2015–2020 (+7,2 procent), och 2020–2025 höll den sig kvar på 6,2 procent, mer än tre gånger Kungsbackas takt samma period. Varberg har därmed gått om Kungsbacka som länets snabbast växande kommun. Falkenberg följer ett liknande men dämpat spår, från 32 000 till 47 000 invånare (+49 procent), med sin kraftigaste ökning kring 2015–2020. Tyngdpunkten i den nordliga tillväxten har alltså glidit söderut, från Göteborgsförorten Kungsbacka mot de egna kuststäderna Varberg och Falkenberg.

Halmstad, Laholm och Hylte

I söder är bilden lugnare och mer stabil. Halmstad, länets största kommun, har vuxit jämnt från 71 000 till 106 000 invånare (+51 procent), utan Kungsbackas dramatiska hopp men med en tydlig förstärkning efter 2010. Laholm har följt en stadig kurva med en enda verklig svacka, 1990-talet, då folkmängden i praktiken stod stilla, innan tillväxten återkom på 2000-talet; i dag har kommunen knappt 27 000 invånare, 42 procent fler än 1970.

sydMatt = komMatt(["Halmstad", "Laholm", "Hylte"])

linjediagram(sydMatt.takt.data, {
  x: "år",
  y: "värde",
  color: "serie",
  title: "Halmstad, Laholm och Hylte",
  caption: "Källa: SCB. Årlig procentuell befolkningsförändring. Övriga kommuner i grått, Halland och riket som referens.",
  measures: [sydMatt.takt, sydMatt.taktAntal, sydMatt.antal, sydMatt.index],
  highlight: ["Halmstad", "Laholm", "Hylte", "Halland (län)", "Riket"],
  colors: ["#0C8C7E", "#FF7E00", "#A51300", "#555555", "#999999"],
  logo: "../logo_farg.svg",
  interactive: true,
  maxHighlights: 8
})















Hylte är länets undantag. Kommunen nådde sin topp redan 1976, med drygt 11 200 invånare, och har sedan dess långsamt krympt till knappt 10 100, åtta procent färre än 1970. Nedgången har inte varit dramatisk men ihållande, störst under 1990-talets andra hälft och, senast, under 2020–2025 då befolkningen minskade med drygt fem procent. I indexform, där 1970 är 100, är Hylte den enda halländska kommunen som ligger under hundra (92), medan de övriga fem stigit långt däröver. Det enda tydliga avbrottet i nedgången var åren kring 2015–2020, då flyktinginvandringen tillfälligt lyfte samtliga halländska kommuner, även Hylte.

Norr drar ifrån söder

Lägger man samman kommunerna i en nordlig och en sydlig halva framträder kapitlets tydligaste geografiska mönster. År 1970 var de två halvorna i stort sett exakt lika stora, omkring 100 000 invånare var. I dag bor 203 000 i de tre nordliga kommunerna mot 143 000 i de tre sydliga: norr har vuxit med 104 procent, söder med 43.

norrSoderMatt = {
  const norr = ["Kungsbacka", "Varberg", "Falkenberg"], soder = ["Halmstad", "Laholm", "Hylte"];
  const years = [...new Set(befutvKommuner.map(d =&gt; d.år))].filter(y =&gt; y &gt;= 1970).sort((a, b) =&gt; a - b);
  const sumAt = (grp, yr) =&gt; d3.sum(befutvKommuner.filter(d =&gt; grp.includes(d.kommun) && d.år === yr), d =&gt; d.befolkning);
  const n70 = sumAt(norr, 1970), s70 = sumAt(soder, 1970);
  const antal = [], idx = [];
  for (const yr of years) {
    const n = sumAt(norr, yr), s = sumAt(soder, yr);
    antal.push({ år: yr, del: "Norra Halland", värde: n });
    antal.push({ år: yr, del: "Södra Halland", värde: s });
    idx.push({ år: yr, del: "Norra Halland", värde: 100 * n / n70 });
    idx.push({ år: yr, del: "Södra Halland", värde: 100 * s / s70 });
  }
  return [
    {
      key: "antal", label: "Antal invånare", filterLabel: "Antal invånare",
      subtitle: "Summerad folkmängd, 1970–2025", data: antal,
      yLabel: "Antal invånare", yMin: 0, formatY: d =&gt; d.toLocaleString("sv-SE")
    },
    {
      key: "index", label: "Index (1970 = 100)", filterLabel: "Index (1970 = 100)",
      subtitle: "Index 100 = år 1970, 1970–2025", data: idx, yLabel: "Index", yMin: "auto",
      hline: { value: 100, dashed: true }, formatY: d =&gt; d.toFixed(0)
    }
  ];
}

linjediagram(norrSoderMatt[0].data, {
  x: "år",
  y: "värde",
  color: "del",
  title: "Norra och södra Halland",
  caption: "Källa: SCB. Norr = Kungsbacka, Varberg, Falkenberg. Söder = Halmstad, Laholm, Hylte.",
  measures: norrSoderMatt,
  highlight: ["Norra Halland", "Södra Halland"],
  colors: ["#0C8C7E", "#A51300"],
  logo: "../logo_farg.svg",
  interactive: true
})















Men gapet öppnades framför allt tidigt. Under 1970- och 1980-talen växte norr nästan tre gånger så snabbt som söder, då Kungsbackas förortsboom var som kraftigast. På senare år har skillnaden krympt: under 2010-talet växte de två halvorna i nästan samma takt. Försprånget är alltså till stor del ett arv från de första decennierna snarare än ett mönster som fortsätter att förstärkas. Förklaringen är geografisk: Göteborgs dragningskraft avtar med avståndet, och ju längre söderut man kommer, desto mer liknar utvecklingen den i södra Sveriges övriga medelstora kommuner. Det betyder inte att söder utvecklats svagt, Halmstads 51 procent överstiger riksgenomsnittet med bred marginal, men den storstadsdrivna tillväxtkorridoren är ett nordhalländskt fenomen.

Befolkningsprognos
Kapitlets sista del blickar framåt. Region Halland gör återkommande befolkningsframskrivningar, och den senaste sträcker sig till 2040. Som påpekades inledningsvis ligger fokus även här på den samlade folkmängdens förändring och inte på de demografiska komponenterna bakom den. Vad som får tillväxttakten att förändras, ett gradvis åldrande, ett vikande födelseöverskott och ett växande beroende av inflyttning, behandlas i den demografiska analys som framskrivningen vilar på. Här är frågan en annan och mer direkt: hur många hallänningar väntas det bli, var, och i vilket tempo jämfört med förr, eftersom det är de faktiska invånartalen som styr behovet av bostäder, skolor och annan samhällsservice.
Prognosen pekar mot en fortsatt men betydligt långsammare tillväxt. Från 346 000 invånare 2025 väntas Halland växa till knappt 360 000 år 2040, en ökning på cirka 13 800 invånare eller 4,0 procent på femton år. Halland fortsätter alltså att växa, men i ett helt annat tempo än tidigare. Under de gångna 25 åren, 2000 till 2025, ökade länet med drygt 71 000 invånare, närmare 26 procent. Den årliga takten faller därmed från knappt en procent till omkring en fjärdedels procent, ungefär en fjärdedel av den historiska. Uttryckt i faktiska tal innebär det att länets årliga folkökning sjunker från i snitt nära 2 800 invånare om året till omkring 900, ungefär en tredjedel av vad Halland vuxit med per år sedan millennieskiftet.

prognosLan = {
  const fmt = d =&gt; d &gt;= 1e6 ? (d / 1e6).toFixed(1) + " mn"
    : d &gt;= 1e3 ? Math.round(d / 1e3) + " k" : d;
  const H = prognos.filter(d =&gt; d.region === "Hallands län").sort((a, b) =&gt; a.år - b.år);
  const popAt = new Map(H.map(d =&gt; [d.år, d.befolkning]));
  const p2000 = popAt.get(2000);

  const folk = [], takt = [], index = [];
  for (const d of H) {
    folk.push({ år: d.år, region: "Halland", värde: d.befolkning });
    index.push({ år: d.år, region: "Halland", värde: 100 * d.befolkning / p2000 });
    const prev = popAt.get(d.år - 1);
    if (prev) takt.push({ år: d.år, region: "Halland", värde: d.befolkning - prev });
  }

  return [
    {
      key: "folk", label: "Folkmängd", filterLabel: "Folkmängd",
      subtitle: "Hallands folkmängd, 2000–2040", data: folk,
      yLabel: "Antal invånare", yMin: 0, formatY: fmt
    },
    {
      key: "takt", label: "Årlig befolkningsförändring", filterLabel: "Årlig förändring (antal)",
      subtitle: "Förändring i antal invånare per år, 2001–2040", data: takt,
      yLabel: "Invånare per år", yMin: "auto", hline: { value: 0, dashed: true },
      formatY: d =&gt; (d &gt; 0 ? "+" : "") + d.toLocaleString("sv-SE")
    },
    {
      key: "index", label: "Index (2000 = 100)", filterLabel: "Index (2000 = 100)",
      subtitle: "Index 100 = år 2000, 2000–2040", data: index,
      yLabel: "Index", yMin: "auto", hline: { value: 100, dashed: true },
      formatY: d =&gt; d.toFixed(0)
    }
  ];
}

linjediagram(prognosLan[0].data, {
  x: "år",
  y: "värde",
  color: "region",
  title: "Hallands befolkning till 2040",
  caption: "Källa: Region Hallands befolkningsframskrivning; utfall till och med 2025 från SCB.",
  measures: prognosLan,
  highlight: ["Halland"],
  colors: ["#0C8C7E"],
  vline: { value: 2025, label: "Prognos", dashed: true },
  logo: "../logo_farg.svg"
})















Bilden av en utdragen inbromsning förstärks om man följer takten i femårssteg. Under tillväxtåren låg den på mellan fyra och sju procent per femårsperiod och kulminerade 2015 till 2020 med sju procent. Redan den senaste uppmätta perioden, 2020 till 2025, föll takten till knappt tre procent, och prognosen pekar mot ännu lägre nivåer: drygt en procent 2025 till 2030, därefter en svag uppgång till omkring en och en halv procent fram till 2040. Takten väntas alltså plana ut långt under det länet vant sig vid, om än utan att för Halland som helhet vända till minskning.

Kommunerna drar isär

Bakom länssiffran ryms stora skillnader, och prognosen ritar delvis om kartan över var i Halland tillväxten sker. Tydligast är att Varberg seglar upp som länets obestridda tillväxtmotor. Kommunen väntas växa med drygt 6 300 invånare till 2040, en ökning på drygt nio procent, och svarar därmed ensam för nära hälften av hela länets prognostiserade tillväxt. Det är en fortsättning på den förskjutning söderut som redan syntes i utfallet, där Varberg på senare år gått om Kungsbacka som länets snabbast växande kommun. Halmstad och Falkenberg följer på avstånd med drygt fyra procents tillväxt var och står tillsammans för knappt halva ökningen, ett mönster där de egna kuststäderna fortsätter att bära utvecklingen.

prognosKommun = {
  const komm = ["Kungsbacka", "Varberg", "Falkenberg", "Halmstad", "Laholm", "Hylte"];
  const index = [], takt = [], taktAntal = [];
  for (const k of komm) {
    const s = prognos.filter(d =&gt; d.region === k).sort((a, b) =&gt; a.år - b.år);
    const popAt = new Map(s.map(d =&gt; [d.år, d.befolkning]));
    const p00 = popAt.get(2000);
    for (const d of s) {
      index.push({ år: d.år, serie: k, värde: 100 * d.befolkning / p00 });
      const prev = popAt.get(d.år - 1);
      if (prev) {
        takt.push({ år: d.år, serie: k, värde: Math.round(1000 * (d.befolkning / prev - 1)) / 10 });
        taktAntal.push({ år: d.år, serie: k, värde: d.befolkning - prev });
      }
    }
  }
  return [
    {
      key: "index", label: "Index (2000 = 100)", filterLabel: "Index (2000 = 100)",
      subtitle: "Index 100 = år 2000. Utfall 2000–2025, prognos 2025–2040.", data: index,
      yLabel: "Index", yMin: "auto", hline: { value: 100, dashed: true }, formatY: d =&gt; d.toFixed(0)
    },
    {
      key: "takt", label: "Årlig befolkningsförändring", filterLabel: "Årlig förändring (%)",
      subtitle: "Procentuell förändring per år. Utfall 2001–2025, prognos 2025–2040.", data: takt,
      yLabel: "% per år", yMin: "auto", hline: { value: 0, dashed: true },
      formatY: d =&gt; d.toLocaleString("sv-SE", { minimumFractionDigits: 1, maximumFractionDigits: 1 }) + " %"
    },
    {
      key: "taktAntal", label: "Årlig befolkningsförändring", filterLabel: "Årlig förändring (antal)",
      subtitle: "Förändring i antal invånare per år. Utfall 2001–2025, prognos 2025–2040.", data: taktAntal,
      yLabel: "Invånare per år", yMin: "auto", hline: { value: 0, dashed: true },
      formatY: d =&gt; (d &gt; 0 ? "+" : "") + d.toLocaleString("sv-SE")
    }
  ];
}

linjediagram(prognosKommun[0].data, {
  x: "år",
  y: "värde",
  color: "serie",
  title: "Kommunernas banor till 2040",
  caption: "Källa: Region Hallands befolkningsframskrivning; utfall till och med 2025 från SCB.",
  measures: prognosKommun,
  highlight: ["Kungsbacka", "Varberg", "Falkenberg", "Halmstad", "Laholm", "Hylte"],
  maxHighlights: 6,
  vline: { value: 2025, label: "Prognos", dashed: true },
  yMin: "auto",
  formatY: d =&gt; d.toFixed(0),
  colors: ["#0C8C7E", "#004990", "#FF7E00", "#A51300", "#8cd211", "#7b2d8e"],
  logo: "../logo_farg.svg",
  interactive: true
})















Mest anmärkningsvärd är Kungsbackas omsvängning. Den kommun som under i stort sett hela perioden sedan 1970 var länets snabbast växande, ofta med över en procent om året, väntas nu nästan stanna av, med en ökning på bara drygt en procent fram till 2040 eller mindre än en tiondels procent om året. Den förortsexpansion söder om Göteborg som en gång byggde Kungsbacka är enligt prognosen i allt väsentligt fullbordad. Laholm växer svagt, med drygt två procent, medan Hylte fortsätter att krympa och nu i snabbare takt än förr. Kommunen väntas tappa drygt nio procent av sin befolkning, närmare tusen invånare, fram till 2040, och blir därmed den enda halländska kommun som väntas vara mindre då än i dag. Inbromsningen är med andra ord inte jämnt fördelad: några kommuner planar ut nära noll, en minskar, medan ett par fortsätter att dra.

Norr och söder i prognosen

Den nord-sydliga skillnad som löpt genom hela kapitlet består även i framskrivningen, men den vilar nu på en annan grund. De tre nordliga kommunerna väntas växa med knappt fem procent till 2040 mot söderns knappa tre, ungefär samma rangordning som under de gångna decennierna. Skillnaden ligger i vad som driver respektive halva. Tidigare bars norr av Kungsbackas Göteborgsdrivna expansion; nu bärs den nästan helt av Varberg, medan Kungsbacka planar ut. I söder håller Halmstad uppe siffran medan Hylte drar ned den. Tyngdpunkten i länets tillväxt fortsätter därmed att glida bort från Göteborgs förortsband i norr och samlas i de egna kuststäderna Varberg och Halmstad.
För planeringen är slutsatsen dubbel. Halland fortsätter att växa, vilket i sig innebär ett fortsatt tryck på bostäder och samhällsservice, men tillväxten blir långsammare och mer ojämn än under de senaste decennierna och koncentreras till ett fåtal kommuner. Var de nya invånarna tillkommer avgörs inte bara av hur många som föds och dör, utan i hög grad av flyttningarna mellan orter och regioner. Just flyttningarna, och den funktionella geografi de ritar upp, ägnar vi ett eget kapitel längre fram i rapporten.

import { linjediagram }       from "../js/grafer/linjediagram.js"
import { linjediagramFacet }  from "../js/grafer/linjediagramFacet.js"
import { stapeldiagram }      from "../js/grafer/stapeldiagram.js"
import { scatterplot }        from "../js/grafer/scatterplot.js"
import { lollipop }           from "../js/grafer/lollipop.js"
import { dotplot }            from "../js/grafer/dotplot.js"
import { stackedArea }        from "../js/grafer/stackedArea.js"
import { beeswarm }           from "../js/grafer/beeswarm.js"
import { beeswarmFacet }      from "../js/grafer/beeswarmFacet.js"
import { grafStepper }        from "../js/grafer/grafStepper.js"
import { karta }              from "../js/kartor/karta.js"
import { createFilterState, createSelectorPanel } from "../js/lib/filterUtils.js"
import { addExportButton } from "../js/lib/exportSvg.js"

