      yLabel: "Antal hushåll",
      yMin: 0,
      formatY: fmtTusen
    },
    {
      key: "folkmangd",
      label: "Folkmängd",
      filterLabel: "Folkmängd",
      subtitle: "Antal invånare, 2011–2025",
      data: data.map(d =&gt; ({ ...d, värde: d.folkmangd })),
      yLabel: "Antal invånare",
      yMin: 0,
      formatY: fmtTusen
    }
  ];
}

